/* Host test for rpd1_core — POSIX I/O backend, no ESP dependencies.
 * Verifies magic/header validation, exact lookups, case-insensitivity,
 * stemming (candidates), punctuation stripping, miss handling and corrupt-file
 * rejection. Fixture generated by gen_fixture.py (build_dict.py-compatible). */
#include "rpd1_core.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static unsigned char* g_blob;
static size_t g_size;

static bool posix_read_at(uint32_t off, void* buf, size_t len, void* ctx) {
  (void)ctx;
  if ((size_t)off + len > g_size) return false;
  memcpy(buf, g_blob + off, len);
  return true;
}
static bool posix_file_size(uint64_t* out, void* ctx) {
  (void)ctx; *out = g_size; return true;
}

static int checks = 0, fails = 0;
#define CHECK(cond, msg) do { ++checks; if (!(cond)) { ++fails; \
  fprintf(stderr, "FAIL: %s (line %d)\n", msg, __LINE__); } } while (0)

static rpd1_sparse_t* s_sparse;
static rpd1_dict_t d;
static rpd1_io_t io;

static void load(const char* path) {
  FILE* f = fopen(path, "rb");
  if (!f) { fprintf(stderr, "cannot open fixture %s\n", path); exit(2); }
  fseek(f, 0, SEEK_END); g_size = ftell(f); fseek(f, 0, SEEK_SET);
  g_blob = malloc(g_size);
  if (fread(g_blob, 1, g_size, f) != g_size) { fprintf(stderr, "short read\n"); exit(2); }
  fclose(f);
  io.read_at = posix_read_at; io.file_size = posix_file_size; io.ctx = NULL;
  s_sparse = calloc(RPD1_SPARSE_MAX, sizeof(rpd1_sparse_t));
  memset(&d, 0, sizeof(d));
}

int main(int argc, char** argv) {
  if (argc < 2) { fprintf(stderr, "usage: rpd1_host_test <fixture.bin>\n"); return 2; }
  load(argv[1]);

  CHECK(rpd1_open(&d, &io, s_sparse, RPD1_SPARSE_MAX), "open valid RPD1");
  CHECK(rpd1_ready(&d), "ready after open");
  CHECK(d.entries == 8, "entries == 8");
  CHECK(d.block_log2 == 4, "block_log2 == 4");
  CHECK(d.sparse_count == 1, "sparse slots == 1 (8 entries < 2^4 block)");

  char out[RPD1_ENTRY_MAX];
  /* exact hits */
  CHECK(rpd1_lookup(&d, "apple", out, sizeof(out)), "hit apple");
  CHECK(strstr(out, "apple; a fruit") != NULL, "apple definition text");
  CHECK(rpd1_lookup(&d, "beautiful", out, sizeof(out)), "hit beautiful");
  CHECK(strstr(out, "adj.") != NULL && strstr(out, "very nice") != NULL, "beautiful multi-line def");
  CHECK(rpd1_lookup(&d, "DOG", out, sizeof(out)), "hit case-insensitive DOG");
  CHECK(strstr(out, "canine") != NULL, "DOG -> canine def");
  /* punctuation stripping: trailing period */
  CHECK(rpd1_lookup(&d, "cat.", out, sizeof(out)), "hit 'cat.' after punctuation strip");
  CHECK(strstr(out, "feline") != NULL, "cat. -> feline def");

  /* stemming: plural -> base form, with [base] hint */
  CHECK(rpd1_lookup(&d, "books", out, sizeof(out)), "stem 'books' -> book");
  CHECK(strstr(out, "[book]") == out, "stem hit prefixes [book]");
  CHECK(strstr(out, "written work") != NULL, "book def text");
  CHECK(rpd1_lookup(&d, "apples", out, sizeof(out)), "stem 'apples' -> apple");
  CHECK(rpd1_lookup(&d, "testing", out, sizeof(out)), "stem 'testing' -> test");

  /* genuine miss */
  CHECK(!rpd1_lookup(&d, "zzzznotaword", out, sizeof(out)), "miss unknown word");
  CHECK(out[0] == 0, "miss clears output");

  /* cap guard */
  CHECK(!rpd1_lookup(&d, "apple", out, 63), "cap<64 rejected");

  rpd1_close(&d);
  CHECK(!rpd1_ready(&d), "not ready after close");

  /* corrupt magic rejected */
  g_blob[0] = 'X';
  CHECK(!rpd1_open(&d, &io, s_sparse, RPD1_SPARSE_MAX), "bad magic rejected");
  g_blob[0] = 'R';

  /* corrupt entries field (0) rejected */
  { uint32_t z = 0; memcpy(g_blob + 12, &z, 4);
    CHECK(!rpd1_open(&d, &io, s_sparse, RPD1_SPARSE_MAX), "entries==0 rejected");
    uint32_t eight = 8; memcpy(g_blob + 12, &eight, 4); }

  printf("rpd1_host_test: %d checks, %d failures\n", checks, fails);
  free(s_sparse); free(g_blob);
  return fails ? 1 : 0;
}
